package com.linqa.app.network

import android.util.Base64
import com.linqa.app.auth.SessionStore
import com.linqa.app.crypto.NativeCore
import java.nio.charset.StandardCharsets
import java.time.Instant
import java.time.temporal.ChronoUnit
import org.json.JSONArray
import org.json.JSONObject

data class ResolvedDevice(
    val deviceId: String,
    val encryptionPublicKey: ByteArray,
    val pqEncryptionPublicKey: ByteArray,
    val signingPublicKey: ByteArray,
)

/**
 * Publishes this device's real, Ed25519-signed hybrid (X25519 + ML-KEM-768)
 * key package — generated by [NativeCore] — and resolves other users'
 * published packages. The server cryptographically verifies every publish
 * against the enrolled device identity
 * (`server/src/auth/key-package-proof.ts::parseAndVerifyKeyPackage`) and
 * only ever serves active, non-expired, non-revoked packages
 * (`server/src/repositories/key-package.repository.ts::findActiveForUser`
 * joins `devices d ON d.status = 'ACTIVE'`), so publish/resolve here do not
 * need to reimplement expiry or revocation filtering — only the signature
 * check, which `NativeSecureCore.verifyKeyPackage` performs locally as a
 * second, independent check before any key is trusted for encryption.
 */
class KeyPackageApi(
    private val api: RealApiClient,
    private val sessions: SessionStore,
) {
    suspend fun publishOwnKeyPackage() {
        val session = sessions.current() ?: error("not authenticated")
        val deviceId = session.deviceId ?: error("device not enrolled")
        val secureCore = NativeCore.instance() ?: error("native secure core not loaded")

        val expiresAt = Instant.now().plus(30, ChronoUnit.DAYS)
        val packageBase64 = secureCore.generateKeyPackage(
            session.userId,
            deviceId,
            expiresAt.epochSecond.toULong(),
        )

        api.put(
            "/v1/devices/$deviceId/key-package",
            JSONObject()
                .put("packageVersion", 2)
                .put("packageBase64", packageBase64)
                .put("expiresAt", expiresAt.toString()),
        )
    }

    /** Returns the newest active, signature-verified device key package for
     * [userId], or null if they have no reachable device. */
    suspend fun resolveDevice(userId: String): ResolvedDevice? {
        val secureCore = NativeCore.instance() ?: error("native secure core not loaded")
        val response = api.get("/v1/users/$userId/key-packages")
        val keyPackages = response.getJSONArray("keyPackages")
        if (keyPackages.length() == 0) return null

        val packageBase64 = keyPackages.getJSONObject(0).getString("packageBase64")
        secureCore.verifyKeyPackage(packageBase64)

        val packageJson = JSONObject(
            String(Base64.decode(packageBase64, Base64.NO_WRAP), StandardCharsets.UTF_8),
        )

        return ResolvedDevice(
            deviceId = packageJson.getString("device_id"),
            encryptionPublicKey = packageJson.getJSONArray("encryption_public_key").toByteArray(),
            pqEncryptionPublicKey = packageJson.getJSONArray("pq_encryption_public_key").toByteArray(),
            signingPublicKey = packageJson.getJSONArray("signing_public_key").toByteArray(),
        )
    }

    private fun JSONArray.toByteArray(): ByteArray =
        ByteArray(length()) { i -> getInt(i).toByte() }
}
